  const intoExists = r.value.customers.some((c) => c.id === 'C-002');

  assert.equal(fromExists, false);
  assert.equal(intoExists, true);
});

test('mergeCustomers reassigns invoices from fromId to intoId', () => {
  const customers = listCustomers();
  const invoices = [
    { customerId: 'C-001', number: 'INV-001', status: 'issued' },
    { customerId: 'C-001', number: 'INV-002', status: 'issued' },
    { customerId: 'C-002', number: 'INV-003', status: 'issued' },
  ];

  const r = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(r.ok, true);

  const c001Invoices = r.value.invoices.filter((inv) => inv.customerId === 'C-001');
  const c002Invoices = r.value.invoices.filter((inv) => inv.customerId === 'C-002');

  assert.equal(c001Invoices.length, 0);
  assert.equal(c002Invoices.length, 3);
});

test('mergeCustomers with normalized IDs', () => {
  const customers = listCustomers();
  const invoices = [
    { customerId: 'C-001', number: 'INV-001', status: 'issued' },
  ];

  const r = mergeCustomers(customers, invoices, 'c-001 ', 'C-002');
  assert.equal(r.ok, true);

  const fromExists = r.value.customers.some((c) => c.id === 'C-001');
  assert.equal(fromExists, false);

  const movedInvoice = r.value.invoices.find((inv) => inv.number === 'INV-001');
  assert.equal(movedInvoice.customerId, 'C-002');
});

test('mergeCustomers rejects if fromId does not exist', () => {
  const customers = listCustomers();
  const invoices = [];

  const r = mergeCustomers(customers, invoices, 'C-999', 'C-001');
  assert.equal(r.ok, false);
  assert.equal(r.error, 'CUSTOMER_NOT_FOUND');
});

test('mergeCustomers rejects if intoId does not exist', () => {
  const customers = listCustomers();
  const invoices = [];

  const r = mergeCustomers(customers, invoices, 'C-001', 'C-999');
  assert.equal(r.ok, false);
  assert.equal(r.error, 'CUSTOMER_NOT_FOUND');
});

test('mergeCustomers rejects if both IDs are the same', () => {
  const customers = listCustomers();
  const invoices = [];

  const r = mergeCustomers(customers, invoices, 'C-001', 'C-001');
  assert.equal(r.ok, false);
  assert.equal(r.error, 'SAME_CUSTOMER');
});

test('mergeCustomers rejects same customer with different cases', () => {
  const customers = listCustomers();
  const invoices = [];

  const r = mergeCustomers(customers, invoices, 'c-001 ', 'C-001');
  assert.equal(r.ok, false);
  assert.equal(r.error, 'SAME_CUSTOMER');
});

test('mergeCustomers does not mutate original arrays', () => {
  const customers = listCustomers();
  const customersCount = customers.length;
  const invoices = [
    { customerId: 'C-001', number: 'INV-001', status: 'issued' },
  ];
  const invoicesCount = invoices.length;

  mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(customers.length, customersCount);
  assert.equal(invoices.length, invoicesCount);
  assert.equal(invoices[0].customerId, 'C-001');
});

