  const r = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(r.ok, true);

  r.value.customers[0].name = 'Changed';
  const c = getCustomer('C-002');
  assert.notEqual(c.value.name, 'Changed');
});

